//! The precompiled ambient AST: the cold-start cache of
//! [`AMBIENT_SOURCE`](crate::AMBIENT_SOURCE)'s expanded tree.
//!
//! The blob is a checked-in artifact, regenerated by the `gen-ambient`
//! example: a 16-byte source-hash header (so a drifted `ambient.ds`
//! refuses to decode) followed by the postcard-encoded tree of a fresh
//! parse through the ds-check derive expansion — the artifact ships
//! pre-expanded trees, so the run path's ownership seam moves the served
//! tree through the expansion pass with no clone and no re-expansion
//! (expansion consumes derive attributes, so a pass over an expanded
//! tree is the identity either way). The loader verifies the header and
//! the decoded tree's file id before serving it; every caller falls back
//! to a fresh parse on any error, so the blob is a pure cache, never
//! correctness-load-bearing. The drift gate
//! (`ambient_blob_matches_a_fresh_expansion`) re-serializes a fresh
//! parse-then-expansion and compares bytes, so any grammar, conversion,
//! expansion, or format change that alters the tree fails the suite
//! until the example regenerates the artifact.

use ds_diag::FileId;
use ds_mod::Hash128;
use ds_parse::Ast;

/// The embedded artifact: source-hash header plus the postcard-encoded
/// expanded tree.
static BLOB: &[u8] = include_bytes!("ambient.ast");

/// The artifact's tree, decoded at most once per process and parked
/// behind one shared handle: every serve hands the same tree out as a
/// reference-counted clone, so a process that compiles many members
/// over one ambient (a package graph's member compiles, a query
/// session) pays the decode once and no tree clone ever — a bundle
/// holding shared trees adopts the resident tree per compile and drops
/// a refcount at teardown. A one-compile-per-process run (a cold `ds
/// run`, the pinned kernels) pays the decode plus one allocation to
/// park it, nothing more. A decode failure stays cached with it: a
/// drifted artifact answers every caller with the same miss, only
/// without re-decoding the bytes per call.
static TREE: std::sync::OnceLock<Result<std::sync::Arc<Ast>, AmbientBlobError>> =
    std::sync::OnceLock::new();

/// The artifact bytes' decode, the once-per-process half of [`ambient_ast`].
fn decode_tree() -> Result<Ast, AmbientBlobError> {
    let Some((header, payload)) = BLOB.split_first_chunk::<HEADER>() else {
        return Err(AmbientBlobError::SourceDrift);
    };
    if header != Hash128::compute(crate::AMBIENT_SOURCE.as_bytes()).as_bytes() {
        return Err(AmbientBlobError::SourceDrift);
    }
    postcard::from_bytes(payload).map_err(AmbientBlobError::Decode)
}

/// The source-hash header's size in bytes.
const HEADER: usize = 16;

/// Why the precompiled ambient AST could not be served.
#[derive(Clone, Debug)]
pub enum AmbientBlobError {
    /// The artifact's source hash does not match `AMBIENT_SOURCE`: the
    /// blob predates a source edit. Regenerate it with the `gen-ambient`
    /// example.
    SourceDrift,
    /// The decoded tree addresses a different file than the caller
    /// registered: the blob's spans carry the file id it was generated
    /// with, so only a first-registered ambient can take the direct hit.
    FileMismatch,
    /// The payload failed to decode.
    Decode(postcard::Error),
}

impl std::fmt::Display for AmbientBlobError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::SourceDrift => f.write_str("the ambient AST artifact is stale"),
            Self::FileMismatch => f.write_str("the ambient AST artifact addresses another file id"),
            Self::Decode(_) => f.write_str("the ambient AST artifact failed to decode"),
        }
    }
}

impl std::error::Error for AmbientBlobError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            Self::Decode(error) => Some(error),
            _ => None,
        }
    }
}

/// The precompiled expanded tree of the ambient member, when the embedded
/// artifact verifies: the source-hash header must match the current
/// [`AMBIENT_SOURCE`](crate::AMBIENT_SOURCE) and the decoded tree must
/// address `file`. Any miss is an error the caller answers with a fresh
/// parse (whose tree the derive expansion then covers at run time).
///
/// `file` is the id the caller registered the ambient under; the blob's
/// tree spans address the file it was generated with, so the standard
/// first-registered discipline takes the direct hit and any other
/// registration falls back.
///
/// # Errors
///
/// [`AmbientBlobError`]: a stale header, a foreign file id, or a decode
/// failure — all of them cache misses, never source problems.
pub fn ambient_ast(file: FileId) -> Result<std::sync::Arc<Ast>, AmbientBlobError> {
    let tree = TREE.get_or_init(|| decode_tree().map(std::sync::Arc::new));
    let tree = tree.as_ref().map_err(Clone::clone)?;
    if tree.file != file {
        return Err(AmbientBlobError::FileMismatch);
    }
    Ok(std::sync::Arc::clone(tree))
}

#[cfg(test)]
mod tests {
    use super::*;

    /// The embedded artifact must byte-match a fresh serialization of a
    /// fresh parse of the current source through the derive expansion:
    /// any grammar, conversion, expansion, or format drift fails here
    /// until `cargo run -p ds-stdlib --example gen-ambient` regenerates
    /// it.
    #[test]
    fn ambient_blob_matches_a_fresh_expansion() {
        let mut files = ds_diag::Files::new();
        let file = files.add_source(crate::AMBIENT_FILE, crate::AMBIENT_SOURCE);
        let ast = ds_parse::parse(&files, file).expect("the ambient parses");
        let (expanded, diags) = ds_meta::expand_derives(&[&ast]);
        assert!(diags.is_empty(), "the ambient derives refuse: {diags:?}");
        let bytes = postcard::to_allocvec(expanded[0].as_ref()).expect("the AST serializes");
        assert_eq!(
            BLOB[..HEADER],
            Hash128::compute(crate::AMBIENT_SOURCE.as_bytes()).as_bytes()[..],
            "the artifact's source hash drifted"
        );
        assert_eq!(
            &BLOB[HEADER..],
            &bytes[..],
            "the ambient AST artifact drifted; regenerate with `cargo run -p ds-stdlib --example \
             gen-ambient`"
        );
        let decoded = ambient_ast(file).expect("the verified artifact decodes");
        let reserialized =
            postcard::to_allocvec(decoded.as_ref()).expect("the served tree reserializes");
        assert_eq!(
            reserialized, bytes,
            "the served tree must be the encoded tree"
        );
    }

    /// The served tree is expansion-final: it carries no derive
    /// attribute, and a second expansion over it is the identity — the
    /// pass the query layer's expansion runs over the blob-served
    /// ambient answers the same trees, never a double expansion.
    #[test]
    fn the_served_tree_is_expansion_final() {
        let mut files = ds_diag::Files::new();
        let file = files.add_source(crate::AMBIENT_FILE, crate::AMBIENT_SOURCE);
        let decoded = ambient_ast(file).expect("the verified artifact decodes");
        let carries_derive = decoded.blocks.iter().any(|block| {
            block
                .items
                .iter()
                .any(|item| item.attrs.iter().any(|attr| attr.name.name == "derive"))
        });
        assert!(
            !carries_derive,
            "the artifact's trees ship pre-expanded, so no derive attribute remains"
        );
        let (reexpanded, diags) = ds_meta::expand_derives(&[decoded.as_ref()]);
        assert!(diags.is_empty(), "an expanded tree re-expands clean");
        let again = postcard::to_allocvec(reexpanded[0].as_ref()).expect("the tree serializes");
        let before = postcard::to_allocvec(decoded.as_ref()).expect("the tree serializes");
        assert_eq!(
            again, before,
            "the expansion over an expanded tree is the identity"
        );
    }

    /// The run path's ownership seam: analyzing the blob-served ambient
    /// (marked pre-expanded) beside a derive-carrying user tree answers
    /// the same bundle as the fresh-parse path — same trees, same
    /// diagnostics — so the ambient's derive-synthesized impls and the
    /// user's answer identically either way.
    #[test]
    fn the_pre_expanded_blob_analyzes_identically_to_a_fresh_parse() {
        let mut files = ds_diag::Files::new();
        let ambient = files.add_source(crate::AMBIENT_FILE, crate::AMBIENT_SOURCE);
        let user_source = "#[derive(show, hash)]\nstruct point { x: int, y: int }\n";
        let user = files.add_source("point.ds", user_source);
        let user_ast = ds_parse::parse(&files, user).expect("the user source parses");
        let served = ambient_ast(ambient).expect("the verified artifact decodes");
        let owned = ds_meta::analyze_owned(
            &files,
            vec![served, std::sync::Arc::new(user_ast.clone())],
            &[true, false],
        );
        let fresh_ambient = ds_parse::parse(&files, ambient).expect("the ambient parses");
        let fresh = ds_meta::analyze(&files, &[fresh_ambient, user_ast]);
        assert_eq!(
            owned.checked.diags, fresh.checked.diags,
            "the served path checks the same package"
        );
        assert_eq!(owned.asts.len(), fresh.asts.len());
        for (served_tree, fresh_tree) in owned.asts.iter().zip(fresh.asts.iter()) {
            let served_bytes =
                postcard::to_allocvec(served_tree.as_ref()).expect("the served tree serializes");
            let fresh_bytes =
                postcard::to_allocvec(fresh_tree.as_ref()).expect("the fresh tree serializes");
            assert_eq!(
                served_bytes, fresh_bytes,
                "the trees must answer identically"
            );
        }
        assert!(
            owned.package.lookup_type("point").is_some(),
            "the user's derive target resolved"
        );
    }

    /// A file id the artifact was not generated under is a cache miss,
    /// never a served tree.
    #[test]
    fn a_foreign_file_id_falls_back() {
        let error = ambient_ast(FileId::new(9)).expect_err("the artifact addresses its own file");
        assert!(matches!(error, AmbientBlobError::FileMismatch));
    }

    /// Every serve of the decoded tree answers the same tree: the
    /// once-per-process decode parks one resident handle and every
    /// serve hands the resident tree out by refcount, so a process that
    /// compiles many members over one ambient serves every one of them
    /// the tree it would have decoded, at no clone.
    #[test]
    fn every_serve_answers_the_same_tree() {
        let mut files = ds_diag::Files::new();
        let file = files.add_source(crate::AMBIENT_FILE, crate::AMBIENT_SOURCE);
        let encoded = |ast: &Ast| postcard::to_allocvec(ast).expect("the served tree serializes");
        let first = encoded(
            ambient_ast(file)
                .as_deref()
                .expect("the first serve decodes"),
        );
        let second = encoded(
            ambient_ast(file)
                .as_deref()
                .expect("the second serve decodes"),
        );
        let third = encoded(
            ambient_ast(file)
                .as_deref()
                .expect("a later serve shares the resident tree"),
        );
        assert_eq!(
            first, second,
            "the resident-parking serve answers the first"
        );
        assert_eq!(first, third, "a later serve clones the resident tree");
    }
}
